+                    d.getTimeStampField(),
+                    d.getIndices(),
+                    d.getGeneration(),
+                    d.getMetadata(),
+                    d.isHidden(),
+                    true,
+                    d.isSystem(),
+                    d.isAllowCustomRouting(),
+                    d.getIndexMode()
+                )
+            )
+            .build();
+
+        now = now.plus(1, ChronoUnit.HOURS);
